window.SEARCH_INDEX = [{"url":"problems/3789-minimum-cost-to-acquire-required-items.html","title":"3789. Minimum Cost to Acquire Required Items","zh":"取得所需物品的最小花費","level":"Medium","series":"每日一題","date":"2026-11-11","nums":[3789],"tags":["數學","貪心"],"desc":"枚舉套餐數量 x，總花費 f(x) 是先降後升的折線，最低點只會在 0、min(need)、max(need) 三個轉折點。換成貪心：配對的部分取 min(costBoth, cost1 + cost2)，單邊剩下的取 min(cost, costBoth)，記得用 long long。","cover":"assets/img/3789-minimum-cost-to-acquire-required-items.jpg"},{"url":"problems/dp04-counting-stairs.html","title":"DP 刷題單 #4 · 計數型爬樓梯","zh":"2466 · 91","level":"Medium","series":"動態規劃刷題單","date":"2026-11-10","nums":[2466,91],"tags":["動態規劃","計數"],"desc":"2466：把字串長度看成樓梯階數，每步爬 zero 或 one 階，dp[i] = dp[i − zero] + dp[i − one]，記得每一步都取餘數。91：每一步先檢查條件，單獨一個數字不能是 0、兩個數字要在 10 到 26 之間，才能從前一階或前兩階走過來。","cover":"assets/img/dp04-counting-stairs.jpg"},{"url":"problems/3693-climbing-stairs-ii.html","title":"3693. Climbing Stairs II","zh":"爬樓梯 II","level":"Medium","series":"每日一題","date":"2026-11-10","nums":[3693],"tags":["動態規劃"],"desc":"每次可以跳 1、2、3 階，從 i 跳到 j 要付 costs[j] + (j − i)²。貪心只看眼前會出錯，改用 dp[j] = min(dp[j−k] + costs[j] + k²)，最後再用三個變數把空間壓到 O(1)。","cover":"assets/img/3693-climbing-stairs-ii.jpg"},{"url":"problems/dp03-delete-and-earn.html","title":"DP 刷題單 #3 · 740. Delete and Earn","zh":"刪除並獲得點數","level":"Medium","series":"動態規劃刷題單","date":"2026-11-10","nums":[740],"tags":["動態規劃"],"desc":"拿了一個 x，剩下的 x 也應該全部拿走，所以決定的單位是「哪一種數字」。把相同數字的點數裝進桶子 sum[v]，相鄰的桶子不能同時選，就變成對桶子陣列跑一次打家劫舍。","cover":"assets/img/dp03-delete-and-earn.jpg"},{"url":"problems/dp02-house-robber-i-ii.html","title":"DP 刷題單 #2 · 打家劫舍 I & II","zh":"198 · 213","level":"Medium","series":"動態規劃刷題單","date":"2026-11-09","nums":[198,213],"tags":["動態規劃"],"desc":"198：先看兩種貪心為什麼錯，再定義 dp[i] = 前 i 間房子能偷到的最多錢，偷或不偷取較大值。213：房子圍成一圈，拆成「不偷最後一間」和「不偷第一間」兩條直線，各跑一次 198 再取較大值。","cover":"assets/img/dp02-house-robber-i-ii.jpg"},{"url":"problems/1606-find-servers-that-handled-most-requests.html","title":"1606. Find Servers That Handled Most Number of Requests","zh":"找到處理最多請求的伺服器","level":"Hard","series":"每日一題","date":"2026-11-09","nums":[1606],"tags":["有序集合","優先佇列"],"desc":"忙碌的伺服器放進按結束時間排序的堆積，空閒的伺服器放進有序集合，用 lower_bound 找「從 i % k 開始往後第一台」空閒伺服器，找不到就繞回開頭。","cover":"assets/img/1606-find-servers-that-handled-most-requests.jpg"},{"url":"problems/dp01-intro.html","title":"DP 刷題單 #1 · 入門","zh":"509 · 1137 · 70 · 746","level":"Easy","series":"動態規劃刷題單","date":"2026-11-08","nums":[509,1137,70,746],"tags":["動態規劃","記憶化"],"desc":"從費氏數列認識動態規劃：遞迴 → 記憶化 → 由下而上填表 → 滾動變數。再用同一套想法解泰波那契、爬樓梯和最小花費爬樓梯。","cover":"assets/img/dp01-intro.jpg"},{"url":"problems/1267-count-servers-that-communicate.html","title":"1267. Count Servers that Communicate","zh":"統計參與通信的伺服器","level":"Medium","series":"每日一題","date":"2026-11-08","nums":[1267],"tags":["計數","矩陣"],"desc":"先數每一列、每一行各有幾台伺服器；一台伺服器只要所在的列或行超過一台，就能通訊。也介紹看成圖、DFS、並查集的另解。","cover":"assets/img/1267-count-servers-that-communicate.jpg"},{"url":"problems/1882-process-tasks-using-servers.html","title":"1882. Process Tasks Using Servers","zh":"使用伺服器處理任務","level":"Medium","series":"每日一題","date":"2026-11-07","nums":[1882],"tags":["優先佇列","模擬"],"desc":"用兩個堆積模擬：空閒伺服器按（權重, 編號）排，忙碌伺服器按空閒時間排。所有伺服器都在忙時，時間直接跳到最早空出來的那一刻。","cover":"assets/img/1882-process-tasks-using-servers.jpg"},{"url":"problems/0042-trapping-rain-water.html","title":"42. Trapping Rain Water","zh":"接雨水","level":"Hard","series":"經典題","date":"2026-11-07","nums":[42],"tags":["雙指針","單調棧","前綴最大值"],"desc":"每一格能裝的水 = 左右最高牆的較小值 − 自己的高度。從暴力法一路優化到雙指針 O(n)、O(1) 空間，再用單調棧換個角度一層一層算。","cover":"assets/img/0042-trapping-rain-water.jpg"}];
